  async function handoffTargets(){const files=[];for(const path of Object.keys(BACKUP_FILES))try{files.push({path,bytes:await readFileBytes(path.split("/"))});}catch(_){}try{files.push({path:"data/recovery.json",bytes:await readFileBytes(RECOVERY_PATH)});}catch(_){}try{const history=await walkFiles(await directory(["data","history"],false),"data/history");files.push(...history);}catch(_){}for(const dirName of [...HANDOFF_CLEAR_DIRS,"Files To Learn"]){try{const items=await walkFiles(await directory([dirName],false),dirName);files.push(...items.filter((item)=>dirName!=="Files To Learn"||HANDOFF_LEARN_PATTERN.test(item.path)));}catch(_){}}for(const name of ["MOONDOG_DIAGNOSTICS.md","PROJECT_CONTEXT.md","README.txt","TEST_STATUS.md","NEW_STORE_HANDOFF_REPORT.md"])try{files.push({path:name,bytes:await readFileBytes([name])});}catch(_){}for await(const[name,handle]of model.root.entries())if(handle.kind==="file"&&HANDOFF_ROOT_SOURCE_PATTERN.test(name)&&!files.some((item)=>item.path===name))files.push({path:name,bytes:new Uint8Array(await(await handle.getFile()).arrayBuffer())});return files;}
  function portableContext(){return`# Service Operations Dashboard - Portable Product Context\n\nVersion: ${VERSION}\nBuild date: ${BUILD_DATE}\n\n## Product architecture\nService Operations Dashboard is an offline, self-contained Microsoft Edge application launched from 00 - OPEN DASHBOARD.html. It requires no installer, executable, local server, background service, internet connection, or development tool at runtime. The user authorizes one working folder; durable normal files in that folder are the source of truth.\n\n## Durable model\nThe data folder contains Open RO state, appointments, advisor performance, operational metrics, Assign Next state, automatic-intake signatures, Settings, meeting-cycle baseline, recovery metadata, and bounded history. Backups are coherent whole-state ZIP packages with a versioned manifest and SHA-256 integrity values. Restore is whole-state only, validates before writing, creates a safety backup first, and verifies after writing.\n\n## Product rules\nGuided Setup requires only confirmed Store identity and a structurally valid SAPR. SAPR discovers advisors; every newly discovered advisor starts with all participation off. CSI, VIR, Menu, Next Appointments, Media ASR, Efficiency, SOR, and aggregate WIP begin Recommended. Customer Communication is fixed: Not recorded, Updated, Attempted / no response, Needs update, Not needed. Controllables progress from SAPR Brand Average to BIC. SAPR owns reporting days.\n\n## Local configuration boundary\nPerformance targets, gross minimums, gross stretch goals, dollar targets, and store-specific standards are stored only in data/settings.json inside the connected workspace. Public application source contains no dealership target values. New-store copies start with those targets unconfigured.\n\n## Operational safety\nUnknown source meaning is never guessed. Unsupported files go to Files To Learn. Critical state is not browser-storage-only. Support packages are sanitized and exclude raw customer, RO, VIN, appointment, CSI, and note data. Prepare for New Store requires strong confirmation and a validated external recovery archive, resets only the currently connected folder, and rolls back if validation fails.\n\n## Continuation rule\nRead this complete file before changes. Preserve working behavior and durable data. Stage and test changes before deployment. Update this file last after verified changes.\n`;}
  function portableReadme(){return`Service Operations Dashboard ${VERSION}\n\nDouble-click 00 - OPEN DASHBOARD.html in Microsoft Edge, choose or reconnect the working folder, and complete Guided Setup. Place supported source reports in 01 - DROP REPORTS HERE. Service Operations Dashboard is offline and self-contained; no installer or internet connection is required at runtime.\n\nStore identity and a valid SAPR are the only global Setup requirements. Other supported sources begin Recommended. Newly discovered advisors begin with participation off.\n\nBackup & Recovery creates validated whole-state backups. Support packages are sanitized. Prepare Service Operations Dashboard for a New Store permanently clears store-specific content from only the connected copy and requires an external safety archive first.\n`;}
  function portableTestStatus(){return`# Service Operations Dashboard Product Verification\n\nVersion ${VERSION}; build ${BUILD_DATE}.\n\nThe packaged deterministic harness is available at test-harness.html. Real Edge permission persistence, OneDrive synchronization, desktop Excel, printers, TV sizing, and store-source mapping require verification in the destination environment.\n`;}
