  async function validateExternalHandoffBackup(bytes){const zip=await JSZip.loadAsync(bytes),manifest=JSON.parse(await zip.file("manifest.json")?.async("string")||"null");if(manifest?.format!=="moondog-external-handoff-safety"||manifest.validationStatus!=="validated")throw new Error("External safety backup manifest is invalid.");for(const entry of manifest.entries||[]){const part=zip.file(entry.path);if(!part)throw new Error(`External safety backup is incomplete: ${entry.path}.`);const data=await part.async("uint8array");if(data.byteLength!==entry.size||await sha256(data)!==entry.sha256)throw new Error(`External safety backup integrity failed: ${entry.path}.`);}const whole=await zip.file("whole-state-backup.zip")?.async("uint8array");if(!whole)throw new Error("External safety backup lacks the Phase 4 whole-state backup.");await validateBackupBytes(whole);return{zip,manifest};}
